using System;using System.Drawing;using System.Drawing.Drawing2D;using System.Globalization;using System.IO;using System.Net;using System.Reflection;using System.Web.Script.Serialization;using System.Windows.Forms;using System.Collections.Generic;
namespace AgentCatScreenSaver{
static class Program{[STAThread]static void Main(string[] a){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);string m=a.Length>0?a[0].ToLowerInvariant():"/c";if(m.StartsWith("/s")||m=="/test")Application.Run(new Saver(m=="/test"));else MessageBox.Show("Agent Cat animated screen saver\n\nUse /test to preview or install.ps1 to configure.","Agent Cat");}}
sealed class Saver:Form{Timer t=new Timer();Timer r=new Timer();DateTime arm;Point mouse;bool preview;float phase;Data d=Data.Load();Random rnd=new Random();List<PointF> stars=new List<PointF>();Image catSheet;
public Saver(bool p){preview=p;DoubleBuffered=true;BackColor=Color.FromArgb(8,12,27);KeyPreview=true;FormBorderStyle=p?FormBorderStyle.Sizable:FormBorderStyle.None;TopMost=!p;ShowInTaskbar=p;WindowState=p?FormWindowState.Normal:FormWindowState.Maximized;if(p){ClientSize=new Size(1280,720);StartPosition=FormStartPosition.CenterScreen;Text="Agent Cat 치즈냥이 화면보호기 미리보기";}if(!p)Cursor.Hide();try{var stream=Assembly.GetExecutingAssembly().GetManifestResourceStream("CheeseCatRunSheet");if(stream!=null)catSheet=Image.FromStream(stream);}catch{}KeyDown+=(s,e)=>{if(!preview)Application.Exit();};MouseDown+=(s,e)=>{if(!preview&&DateTime.UtcNow>arm)Application.Exit();};MouseMove+=(s,e)=>{if(preview||DateTime.UtcNow<arm)return;if(Math.Abs(Cursor.Position.X-mouse.X)>8||Math.Abs(Cursor.Position.Y-mouse.Y)>8)Application.Exit();};t.Interval=30;t.Tick+=(s,e)=>{phase+=.12f;Invalidate();};r.Interval=5000;r.Tick+=(s,e)=>{d=Data.Load();Invalidate();};Shown+=(s,e)=>{arm=DateTime.UtcNow.AddSeconds(1);mouse=Cursor.Position;for(int i=0;i<70;i++)stars.Add(new PointF(rnd.Next(Math.Max(1,Width)),rnd.Next(Math.Max(1,Height))));t.Start();r.Start();};}
protected override void OnPaint(PaintEventArgs e){var g=e.Graphics;g.SmoothingMode=SmoothingMode.AntiAlias;g.Clear(Color.FromArgb(8,12,27));foreach(var p in stars){int a=(int)(35+70*(Math.Sin(phase+p.X)+1)/2);using(var b=new SolidBrush(Color.FromArgb(a,180,210,255)))g.FillEllipse(b,p.X,p.Y,2,2);}float s=Math.Max(.65f,Math.Min(Width/1280f,Height/720f));using(var f=new Font("Segoe UI",27*s,FontStyle.Bold,GraphicsUnit.Pixel))using(var b=new SolidBrush(Color.White))g.DrawString("AGENT CAT",f,b,50*s,35*s);using(var f=new Font("Segoe UI",13*s,FontStyle.Regular,GraphicsUnit.Pixel))using(var b=new SolidBrush(Color.FromArgb(150,170,200)))g.DrawString("LOCAL ACTIVITY MONITOR",f,b,245*s,50*s);DrawCat(g,Width*.28f,Height*.5f,Math.Min(Width,Height)*.34f,s);DrawPanel(g,s);using(var f=new Font("Malgun Gothic",10*s,FontStyle.Regular,GraphicsUnit.Pixel))using(var b=new SolidBrush(Color.FromArgb(110,135,165)))g.DrawString("로컬 메타데이터만 사용 · 입력하면 종료",f,b,Width/2-120*s,Height-35*s);}
	void DrawPanel(Graphics g,float s){float x=Width*.52f,y=Height*.13f,w=Width*.43f,h=Height*.73f;using(var b=new SolidBrush(Color.FromArgb(105,18,30,52)))g.FillRoundedRectangle(b,x,y,w,h,28*s);using(var f=new Font("Malgun Gothic",15*s,FontStyle.Bold,GraphicsUnit.Pixel))using(var b=new SolidBrush(Color.FromArgb(202,218,240)))g.DrawString("로컬 에이전트 사용량",f,b,x+26*s,y+20*s);ProviderCard(g,x+24*s,y+57*s,w-48*s,154*s,"CODEX",d.codex,d.today,d.week,d.month,d.quota,d.codexCount,Color.FromArgb(83,211,150),s);ProviderCard(g,x+24*s,y+226*s,w-48*s,154*s,"CLAUDE",d.claude,d.claudeToday,d.claudeWeek,d.claudeMonth,d.claudeQuota,d.claudeCount,Color.FromArgb(224,145,95),s);using(var f=new Font("Malgun Gothic",11*s,FontStyle.Regular,GraphicsUnit.Pixel))using(var b=new SolidBrush(Color.FromArgb(145,166,194))){string active="활동: Codex "+d.codexCount+" · Claude "+d.claudeCount+" · Gemini "+d.geminiCount+" · "+d.stage;g.DrawString(active,f,b,x+27*s,y+h-32*s);}}
	void ProviderCard(Graphics g,float x,float y,float w,float h,string name,string status,long today,long week,long month,double? quota,int active,Color accent,float s){using(var bg=new SolidBrush(Color.FromArgb(72,63,83,116)))g.FillRoundedRectangle(bg,x,y,w,h,18*s);using(var dot=new SolidBrush(status=="ok"?accent:Color.FromArgb(104,124,151)))g.FillEllipse(dot,x+16*s,y+17*s,9*s,9*s);using(var f=new Font("Segoe UI",14*s,FontStyle.Bold,GraphicsUnit.Pixel))using(var b=new SolidBrush(Color.FromArgb(241,246,255)))g.DrawString(name,f,b,x+32*s,y+10*s);string state=status=="ok"?(active>0?"RUNNING":"CONNECTED"):status=="no_telemetry_yet"?"WAITING FOR DATA":"NOT CONNECTED";using(var f=new Font("Segoe UI",10*s,FontStyle.Bold,GraphicsUnit.Pixel))using(var b=new SolidBrush(status=="ok"?accent:Color.FromArgb(130,150,178))){SizeF z=g.MeasureString(state,f);g.DrawString(state,f,b,x+w-z.Width-15*s,y+13*s);}using(var f=new Font("Segoe UI",25*s,FontStyle.Bold,GraphicsUnit.Pixel))using(var b=new SolidBrush(Color.White))g.DrawString(status=="ok"?Fmt(today):"—",f,b,x+16*s,y+38*s);using(var f=new Font("Malgun Gothic",10*s,FontStyle.Regular,GraphicsUnit.Pixel))using(var b=new SolidBrush(Color.FromArgb(155,176,204))){g.DrawString("오늘",f,b,x+17*s,y+76*s);g.DrawString("7일 "+(status=="ok"?Fmt(week):"—")+"   ·   30일 "+(status=="ok"?Fmt(month):"—"),f,b,x+17*s,y+101*s);string q=quota.HasValue?"노출 쿼터 잔여 "+quota.Value.ToString("0.#")+"%":"정확한 쿼터 정보 없음";g.DrawString(q,f,b,x+17*s,y+126*s);}}
	void DrawCat(Graphics g,float cx,float cy,float z,float s){if(catSheet==null)return;bool sprint=d.stage=="sprinting";bool providerActive=d.codexCount+d.claudeCount+d.geminiCount>0;bool run=d.stage=="running"||d.stage=="walking"||providerActive;int row=sprint?2:run?1:0;float frameRate=sprint?7.5f:run?6f:3.5f;int frame=((int)(phase*frameRate))%6;float sw=catSheet.Width/6f,sh=catSheet.Height/5f;float runWidth=z*1.62f,runHeight=runWidth*(sh/sw);float x=cx-runWidth*.5f;float y=cy-runHeight*.5f+(float)Math.Sin(phase*frameRate)*3*s;g.InterpolationMode=InterpolationMode.HighQualityBicubic;g.PixelOffsetMode=PixelOffsetMode.HighQuality;using(var shadow=new SolidBrush(Color.FromArgb(52,0,0,0)))g.FillEllipse(shadow,x+runWidth*.13f,y+runHeight*.79f,runWidth*.74f,runHeight*.12f);RectangleF dst=new RectangleF(x,y,runWidth,runHeight);RectangleF src=new RectangleF(frame*sw,row*sh,sw,sh);g.DrawImage(catSheet,dst,src,GraphicsUnit.Pixel);if(run||sprint)using(var pen=new Pen(Color.FromArgb(sprint?130:92,110,194,255),3.0f*s)){float sy=y+runHeight*.45f;for(int i=0;i<3;i++){float len=(48+i*20)*s;g.DrawLine(pen,x-len-16*s,sy+i*20*s,x-13*s,sy+i*20*s);}}}
static void Head(Graphics g,float x,float y,float r,Color fur,Color cream,Color ink,bool asleep){PointF[] l={new PointF(x-r*.75f,y-r*.45f),new PointF(x-r*.48f,y-r*1.05f),new PointF(x-r*.12f,y-r*.58f)},q={new PointF(x+r*.12f,y-r*.58f),new PointF(x+r*.48f,y-r*1.05f),new PointF(x+r*.75f,y-r*.45f)};using(var b=new SolidBrush(fur)){g.FillPolygon(b,l);g.FillPolygon(b,q);g.FillEllipse(b,x-r*.78f,y-r*.7f,r*1.56f,r*1.35f);}using(var b=new SolidBrush(cream))g.FillEllipse(b,x-r*.43f,y+r*.02f,r*.86f,r*.48f);using(var p=new Pen(ink,Math.Max(2,r*.055f))){p.StartCap=p.EndCap=LineCap.Round;if(asleep){g.DrawArc(p,x-r*.48f,y-r*.1f,r*.34f,r*.24f,10,160);g.DrawArc(p,x+r*.14f,y-r*.1f,r*.34f,r*.24f,10,160);}else using(var b=new SolidBrush(ink)){g.FillEllipse(b,x-r*.39f,y-r*.11f,r*.14f,r*.19f);g.FillEllipse(b,x+r*.25f,y-r*.11f,r*.14f,r*.19f);}g.DrawLine(p,x-r*.08f,y+r*.15f,x,y+r*.22f);g.DrawLine(p,x+r*.08f,y+r*.15f,x,y+r*.22f);}}
static string Fmt(long n){if(n>=1000000000)return(n/1e9).ToString("0.00",CultureInfo.InvariantCulture)+"B";if(n>=1000000)return(n/1e6).ToString("0.0",CultureInfo.InvariantCulture)+"M";if(n>=1000)return(n/1e3).ToString("0.0",CultureInfo.InvariantCulture)+"K";return n.ToString("N0");}
}
sealed class Data{public string stage="sleeping",codex="unknown",claude="unknown",gemini="unknown";public long today,week,month,claudeToday,claudeWeek,claudeMonth;public int processes,codexCount,claudeCount,geminiCount;public double? quota,claudeQuota;public static Data Load(){string j=null;try{var r=(HttpWebRequest)WebRequest.Create("http://127.0.0.1:8765/v1/snapshot");r.Timeout=1400;using(var x=(HttpWebResponse)r.GetResponse())using(var q=new StreamReader(x.GetResponseStream()))j=q.ReadToEnd();}catch{try{j=File.ReadAllText(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),".agentcat","latest-snapshot.json"));}catch{}}if(String.IsNullOrWhiteSpace(j))return new Data();try{var s=new JavaScriptSerializer{MaxJsonLength=Int32.MaxValue};var root=s.DeserializeObject(j)as Dictionary<string,object>;var d=new Data();var a=Dict(root,"activity");d.stage=Txt(a,"motionStage","sleeping");d.processes=(int)Num(a,"processCount");var counts=Dict(a,"countsByProvider");d.codexCount=(int)Num(counts,"codex");d.claudeCount=(int)Num(counts,"claude");d.geminiCount=(int)Num(counts,"gemini");var ps=Dict(root,"providers");var c=Dict(ps,"codex");var cl=Dict(ps,"claude");d.codex=Txt(c,"status","unknown");d.claude=Txt(cl,"status","unknown");d.gemini=Txt(Dict(ps,"gemini"),"status","unknown");var tok=Dict(c,"tokens");d.today=Num(tok,"today");d.week=Num(tok,"week");d.month=Num(tok,"month");var ctok=Dict(cl,"tokens");d.claudeToday=Num(ctok,"today");d.claudeWeek=Num(ctok,"week");d.claudeMonth=Num(ctok,"month");d.quota=Quota(c);d.claudeQuota=Quota(cl);return d;}catch{return new Data();}}
static Dictionary<string,object> Dict(Dictionary<string,object>d,string k){object v;if(d!=null&&d.TryGetValue(k,out v))return v as Dictionary<string,object>??new Dictionary<string,object>();return new Dictionary<string,object>();}static string Txt(Dictionary<string,object>d,string k,string f){object v;return d!=null&&d.TryGetValue(k,out v)&&v!=null?Convert.ToString(v,CultureInfo.InvariantCulture):f;}static long Num(Dictionary<string,object>d,string k){object v;try{return d!=null&&d.TryGetValue(k,out v)&&v!=null?Convert.ToInt64(v,CultureInfo.InvariantCulture):0;}catch{return 0;}}static double? Quota(Dictionary<string,object>provider){var lim=Dict(provider,"limits");var qs=lim.ContainsKey("quotas")?lim["quotas"]as object[]:null;double? first=null;if(qs!=null)foreach(var o in qs){var q=o as Dictionary<string,object>;if(q==null||!q.ContainsKey("remainingPercent")||q["remainingPercent"]==null)continue;double value=Convert.ToDouble(q["remainingPercent"],CultureInfo.InvariantCulture);if(!first.HasValue)first=value;if(Txt(q,"window","")=="7d")return value;}return first;}}
static class Ext{public static void FillRoundedRectangle(this Graphics g,Brush b,float x,float y,float w,float h,float r){using(var p=new GraphicsPath()){p.AddArc(x,y,r,r,180,90);p.AddArc(x+w-r,y,r,r,270,90);p.AddArc(x+w-r,y+h-r,r,r,0,90);p.AddArc(x,y+h-r,r,r,90,90);p.CloseFigure();g.FillPath(b,p);}}}
